SELECT c.promoTypes
FROM cards c
WHERE c.name = 'Duress';

SELECT c.id
FROM cards c
WHERE c.duelDeck = 'a';

SELECT s.code
FROM sets s
WHERE s.type = 'expansion';

SELECT c.types
FROM cards c
WHERE c.name = 'Molimo, Maro-Sorcerer';

SELECT COUNT(*) AS badge_count
FROM badges
WHERE Name = 'Revival';

SELECT COUNT(*) 
FROM gasstations 
WHERE Country = 'CZE' AND Segment = 'Premium';

SELECT COUNT(*) 
FROM circuits 
WHERE location = 'Adelaide' AND country = 'Australia';

SELECT COUNT(DISTINCT driverId) 
FROM driverStandings 
WHERE raceId = 18;

SELECT COUNT(*) 
FROM member 
WHERE position = 'President';

SELECT a.element
FROM atom a
WHERE a.atom_id = 'TR000_1';
